script.groovy:
import java.math.RoundingMode
// Body kesinlikle Map nesnesidir def json = exchange.message.body
def processedDate = json.processed_date def rates = json.data.rates def base = (json.data.base != null) ? json.data.base : "EUR"
Map currentRates = [:] currentRates[base] = 1.0G rates.each { k, v -> currentRates[k] = new BigDecimal(v.toString()) }
BigDecimal tryRate = currentRates['TRY']
def camelContext = exchange.getContext() Map previousRates = camelContext.getRegistry().lookupByNameAndType("PREVIOUS_RATES_STORE", Map.class) if (previousRates == null) { previousRates = new java.util.concurrent.ConcurrentHashMap() camelContext.getRegistry().bind("PREVIOUS_RATES_STORE", previousRates) }
def results = []
currentRates.each { symbol, rate -> BigDecimal prevRate = previousRates[symbol] BigDecimal nominalDiff = 0.0G BigDecimal percentageDiff = 0.0G
if (prevRate != null && prevRate != 0) { nominalDiff = rate - prevRate percentageDiff = (nominalDiff / prevRate).setScale(6, RoundingMode.HALF_UP) * 100G }
BigDecimal tryEquivalent = 0.0G if (tryRate != null && rate != 0) { tryEquivalent = (tryRate / rate).setScale(4, RoundingMode.HALF_UP) }
BigDecimal displayPrevRate = (prevRate != null) ? prevRate : rate
results.add([ "processed_date": processedDate, "symbol": symbol, "rate": rate.setScale(6, RoundingMode.HALF_UP), "previous_rate": displayPrevRate.setScale(6, RoundingMode.HALF_UP), "nominal_diff": nominalDiff.setScale(6, RoundingMode.HALF_UP), "percentage_diff": percentageDiff.setScale(4, RoundingMode.HALF_UP), "try_equivalent": tryEquivalent ])
previousRates[symbol] = rate }
// Mesaj gövdesini BigQuery'nin kabul ettiği List<Map> nesnesine eşitliyoruz exchange.message.body = results
